import re, os

root = "src"
files = []
for dirpath, _, filenames in os.walk(root):
    for f in filenames:
        if f.endswith(('.ts', '.tsx')):
            files.append(os.path.relpath(os.path.join(dirpath, f), root))

def resolve(importer, spec):
    base = os.path.normpath(os.path.join(os.path.dirname(importer), spec))
    candidates = [base + '.ts', base + '.tsx', os.path.join(base, 'index.ts'), os.path.join(base, 'index.tsx')]
    for c in candidates:
        if c in files:
            return c
    return None

deps = {f: set() for f in files}
for f in files:
    path = os.path.join(root, f)
    with open(path) as fh:
        content = fh.read()
    for m in re.finditer(r"from\s+['\"](\.\.?/[^'\"]+)['\"]", content):
        spec = m.group(1)
        target = resolve(f, spec)
        if target and target != f:
            deps[f].add(target)

for f in sorted(files):
    print(f)
    for d in sorted(deps[f]):
        print("  ->", d)

# count imported-by
count = {f: 0 for f in files}
for f, ds in deps.items():
    for d in ds:
        count[d] += 1

print("\n--- Most imported ---")
top = sorted(count.items(), key=lambda x: -x[1])[:5]
for f, c in top:
    print(f, c)
